
namespace NasaApodGallery.Models // Namespace for application models
{
    // Represents one APOD record stored in SQL Server
    public class Apod
    {
        // Unique ID generated by SQL Server
        public int Id { get; set; }

        // Date of the astronomy picture
        public DateTime Date { get; set; }

        // Title of the picture
        public string Title { get; set; } = "";

        // Explanation provided by NASA
        public string Explanation { get; set; } = "";

        // URL of the image or video
        public string Url { get; set; } = "";

        // Media type: image or video
        public string MediaType { get; set; } = "";

        // NASA API service version
        public string ServiceVersion { get; set; } = "";

        // Date and time when the record was saved
        public DateTime SavedAt { get; set; }
    }
}
